quests[86896] = { id = 86896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Finds a Way", description = "I am an expert in the fauna of Eversong, and I can say with certainty that the vast majority of the wildlife here tend to be of fairly average size.\n\nBut these Light-frenzied saptors are decidedly, unequivocally not. One bite from those thorny jaws could claim the lives of half a dozen Farstriders, if they are caught unawares.\n\nMy rangers have their quivers full culling the chaff alongside the haranir. See to it that those towering tyrannosaptors don't catch them unawares.", completion = "Between you and our new haranir allies, my rangers have plenty of ferocious examples to follow. I'll have to consider teaching some of your techniques at the Retreat.", objectives = "Slay 3 Lightfrenzy Tyrannosaptors in Lightbloom Lash'ra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86897] = { id = 86897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quelling the Frenzy", description = "The day is nearly won. The sin'dorei cull every new sprout that blooms, and the Hara'ti ward the surrounding wilds against the frenzy's influence. All that yet remains is to remove this lightbound serpent's misguided head.\n\nRootwarden Ruia has opposed our every action and shouted down our every word. But he is still a Rootwarden, and one with the power of a frenzying Lightbloom host at his beck and call.\n\nHe is strong. But he does not walk with Aln'hara.\n\nIt is time to end this.", completion = "It is over. Though the Lightbloom may never fully recede, its mastermind has been driven back into the rootway. With the frenzy quelled, and the surrounding forests warded against its advance, we can rest assured that Eversong will not suffer the Lightbloom's spread any longer.\n\nWe've done it. We've won!", objectives = "Confront Lightwarden Ruia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86898] = { id = 86898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Haranir", description = "It is done. The frenzy is routed, the Rootwarden has fled, and the sin'dorei have reclaimed control of their forests.\n\nI can scarcely believe it, but... we succeeded, {name}. By Aln'hara's grace, we found a path forward.\n\nNow Halduron's people invite us to their den. I am not fond of your surface-cities, but...\n\nYou have aided me so many times, my friend. It is time that the Hara'ti reached out hands of our own.", completion = "For the first time in generations, the haranir walk upon the surface of Aln'hara's creation. Time will tell how her creation receives us in turn.\n\nThe fighting is far from over. The Void claws at your gates and threatens your people. But know this, my friend: from this day forward, any threat that encroaches upon Aln'hara's bounty will have the Hara'ti to contend with, be it here or deep below the earth.", objectives = "Meet Orweyna and Halduron in the Gardens of Remembrance in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86899] = { id = 86899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root Cause", description = "The rutaani who attacked Silvermoon come from my homeland, Harandar. This Lightbloom infection is new, however.\n\nThe time has come for me to return to my people. I will face their judgement, and explain my actions.\n\nIf the Lightbloom has spread, I must warn my people of the danger. If you're willing to join me, I will take you and your insistent friend through the rootways to Harandar.\n\nLet me know when you are ready to go.", completion = "You made it. For a moment I wasn't sure you would. Don't worry--that nauseous feeling will pass.\n\nWe stand in the deep roots of Amirdrassil. My home lies beyond.\n\nLet us see what welcome awaits.", objectives = "Take the portal and meet Orweyna in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86900] = { id = 86900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Har'athir", description = "All of the world's roots grow toward our homeland. The ones above you are mighty, but new--born of a fledgling World Tree you call Amirdrassil.\n\nAs far as World Trees go, it is a strange one. But its nature matters less than its reach. Any roots that seek to protect our world from harm are worth protecting.\n\nLet us follow the road down to Har'athir and check in with the Rootwarden. We will ask if he's noticed signs of Lightbloom yet.", completion = "Outsiders are not permitted in Harandar. Orweyna has broken our most sacred of laws.\n\nYou are not welcome here, stranger.", objectives = "Follow Orweyna into Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86901] = { id = 86901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rift and the Den", description = "As I suspected, the elders are quite upset with my actions. Now that I have seen the children and Ku'paal to safety, I am ready to face the Council.\n\nI will do what I can to make them see that the Lightbloom is a threat, and to enable your ability to move freely through Harandar.\n\nPetalvane will carry you safely to the Den. Let us make haste.", completion = "Tread carefully, {name}. The haranir are formidable and on edge over our arrival.\n\nThe Council has convened and is ready to hear Orweyna's words. Hopefully she will be able to convince them that the Lightbloom is a threat and that their help is needed.", objectives = "Ride Petalvane to the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86902] = { id = 86902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relinquishing Relics", description = "My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough.\n\nQuickly, deliver these relics to our friends.", progress = "Did you get those relics out to everyone, {name}?", completion = "With those relics, they should be able to sustain the ritual for much longer.\n\nAnd we can attend to other matters.", objectives = "Distribute relics to Taelia, Valunei, Salandria, and Mehlar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86903] = { id = 86903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcantina", progress = "This really is quite the place, isn't it, {name}?", completion = "This has been a journey, {name}.\n\nI've learned a lot from Alonsus, and the Sons of Lothar...\n\nAnd perhaps most of all, what kind of paladin my father used to be, and what sort I'll be from now on.", objectives = "Visit the Arcantina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86905] = { id = 86905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No More Sick Days", description = "When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again?\n\nWhen you're done see my assistant for payment.", objectives = "Clear out 8 diseased creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86907] = { id = 86907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Den of Echoes", description = "Greetings, stranger. I am Elder Hagar. You have been granted permission to stay, as long as you pass through the trials of the Den of Echoes. \n\nAln'hara will determine your fate, and you will learn about our people and customs.\n\nLet us meet at the caves.", completion = "Welcome to the Den of Echoes. Within the caves beyond, you will find ancient paintings which tell the story of the haranir.\n\nPerhaps you will learn something, if you survive. May Aln'hara be on your side.", objectives = "Meet Hagar at the Den of Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86910] = { id = 86910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koozat's Trample", description = "Koozat is usually very docile. This isn't like him at all. Please, find out what happened.", progress = "Koozat is not usually a violent creature.", completion = "Koozat is the least of our troubles right now. The Lightbloom has arrived. Har'mara is under attack!", objectives = "Follow Orweyna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86911] = { id = 86911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes and Memories", description = "The history of the haranir has been recorded for tens of thousands of years in the caves within. The memories of our people are painted on the stone, that we might never forget where we came from and what our purpose is.\n\nYou are the first outsiders to ever witness the Den of Echoes. When you touch the paintings, our ancestors will share our stories and struggles.\n\nZur'ashar Kassameh awaits you within. He will guide you and Halduron on your journeys. I wish you luck.", progress = "Our people have been here for tens of thousands of years, but it was not always so. Once, we lived on the surface as you do.", completion = "You have made it through the first of the trials, but the real test is yet to come.", objectives = "Complete the first vision of the Den of Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86912] = { id = 86912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Rootways", description = "You have gained a glimpse into our history. There is one trial yet remaining.\n\nIf you survive, the goddess's blessing will be upon you, and the Council will not be able to deny your presence here.\n\nDescend now into the earth and follow in our ancestors' footsteps.", progress = "You have survived the Gulf of Memories. Welcome to Har'mara, friend.", completion = "You awaken. Good. Now that you have seen our past, I have brought you to my home, to see my hope for the future.\n\nHere in Har'mara, we live in harmony with two of the local peoples: the rutaani, and the fungarians. It is my dream that this partnership will spread to the rest of Harandar.\n\nYou should get to know them as well, and see the peace that we have created together.", objectives = "Complete the Gulf of Memories delve and obtain the Fragment of Revelation from its treasure room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86913] = { id = 86913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hut in Har'mara", description = "The others have gathered downstairs. Come. Orweyna is eager to see that you are in one piece.", completion = "Welcome to Har'mara. I am glad to see you well and whole after the trials.\n\nThis village is the home of Hagar and many others who call Harandar their home.", objectives = "Meet Orweyna in Har'mara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86914] = { id = 86914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending to Har'mara", description = "Har'mara has long been a refuge for those who have removed themselves from the conflicts that often arise between the rutaani and the fungarians. \n\nHere, they learn how to live with one another. They work, play, and live together--balanced.\n\nYou have learned much about the past of the haranir, including our deepest shame. Now you will see our current work: harmony.", progress = "It is the natural state of the fungarians and the rutaani to spread themselves out. At times, this can lead to overgrowth and the crowding out of other species.\n\nMaintaining that balance is important, and is the duty the haranir fulfill as stewards of Harandar.", completion = "Sometimes harmony and friendship are helped by small acts of service.\n\nI hope that the rutaani and fungarians here have come to see you as an ally.", objectives = "Complete tasks in Har'mara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86915] = { id = 86915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side with a Cartel" }
quests[86917] = { id = 86917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Right" }
quests[86918] = { id = 86918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Scrap" }
quests[86919] = { id = 86919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Gig" }
quests[86920] = { id = 86920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Mode Violence" }
quests[86921] = { id = 86921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is a repro test", description = "Some sickly looking wolves have descended upon the neighborhood and are wrecking havoc with property values! \n\nWe'll never attract new residents at this rate! Could you please get rid of them?" }
quests[86923] = { id = 86923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Fish" }
quests[86924] = { id = 86924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotta Catch at Least a Few" }
quests[86929] = { id = 86929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council Assembles", description = "Guards collected Orweyna and took her to get ready to meet the Council. When you are ready, we should attend the gathering.", completion = "To stay among us, it must be proven that the goddess has indeed called you to her aid. \n\nYou will undergo trials at the Den of Echoes, a holy place for our people.", objectives = "Attend the Council meeting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86930] = { id = 86930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Sow the Seed", description = "Eonka's seed from Rift of Aln is the clue we were looking for. The inhabitants and plants there seem immune to the Lightbloom!\n\nWe must investigate the rift for ourselves. Let us return to the Den and plan our next moves.", completion = "We return to where we started, but this time you have been blessed by the goddess and we have evidence that the spread of the Lightbloom may be stalled!\n\nThe way forward is not yet clear, but I feel that we are closer.", objectives = "Return to the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86934] = { id = 86934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trash to Profit", description = "Ey! I heard you've been cleanin' up some of the trash around Undermine. Good on ya.\n\nAny interest in takin' that more literally?\n\nIt's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation.\n\nTell him I sent ya so I get my recruitment bonus!", completion = "Renzi's really been rackin' up the recruits lately. You're gonna have some competition!", objectives = "Talk to Carlo Greasegrind at Undermine Sanitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86935] = { id = 86935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On-the-Job Training", description = "If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\"\n\nWe go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'.\n\nFind somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes.\n\nBut I mean, it's trash shovelin', not rocket surgery.", progress = "You might wanna invest in some eye protection. Or at least some really thick gloves. Maybe nose plugs.", completion = "Ah, I love the smell of profit at an ambiguous time of day.\n\nIf you wanna make some more moolah, find me out in the field again. We're gonna do real good work together.", objectives = "Check out Angelo Rustbin's wares inside Undermine Sanitation, then complete a S.C.R.A.P. job in Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86936] = { id = 86936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warped Wood", description = "Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job.  \n\nIf you could clear out a few it would really help speed up our construction efforts.", objectives = "Kill 3 Rotting Treants", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86937] = { id = 86937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healthy Home Certified", description = "We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources.  Do us a favor and get rid of him?\n\nAs always, see my assistant for payment.", objectives = "Kill the Xarn Felhoof", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86938] = { id = 86938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Perforations" }
quests[86939] = { id = 86939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight's Wedge" }
quests[86941] = { id = 86941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Infusion" }
quests[86942] = { id = 86942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Spread", description = "Powdercap said that the visiting travelers were the first to show signs of the Lightbloom infection--right after you questioned them!\n\nSadly, it seems Koozat has also fallen to the sickness. Take out the merchants and see to Koozat as well. He's far too dangerous a creature to be trampling around here.", progress = "I raised Koozat since he was small enough to fit in my hands. The Lightbloom does not discriminate who it infects.", completion = "It is done, then. I grieve that this was necessary, but the corruption needed to be pruned before it could spread further.", objectives = "Slay the visiting rutaani merchants and Koozat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86943] = { id = 86943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drilling Down", objectives = "Defeat the Precision Powerdrill in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86944] = { id = 86944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Rift", description = "The situation is stabilizing, but let's make sure we're in the clear. I will see how Hagar is faring.\n\nCheck on Eonka again and be sure that she's not showing any signs of Lightbloom. She is on an upper level in Hagar's Hut.", progress = "Let us hope Eonka is unchanged.", completion = "Eonka and her seeds are not affected by the Lightbloom. Incredible! Could there be something about the rift that keeps the Lightbloom in check?", objectives = "Check on Eonka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86945] = { id = 86945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowed Supplies" }
quests[86946] = { id = 86946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwrapped and Unraveled", description = "Seeing you two on the battlefield was beautiful. It really is wonderful watching you work. If only your so-called friends had trusted you with the truth of their actions so long ago. Locus-Walker hasn't tried to deceive you with his actions in the present, though his actions in the past that led us to this point... he has been less than forthcoming about.\n\nIn all good conscience, I cannot continue hiding the truth from you or Alleria.", completion = "This is just like the Harbinger to fulfill her oaths to the letter, but leave her allies devastated. If there was any other way to stop the All-Devouring from rising once more...\n\nWith my Reshii Ribbon, you are a step closer toward reaching Dimensius. But you will need at least twice as many to get a force large enough past his dread aura. Good luck, {name}. Watch the Harbinger's every move.", objectives = "Find Alleria before she confronts Locus-Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86947] = { id = 86947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiny, Expensive, and Deadly", objectives = "Defeat Baxx the Purveyor in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86948] = { id = 86948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Bonds" }
quests[86949] = { id = 86949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Crewmates", objectives = "Defeat Prezly Wavecutter in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86951] = { id = 86951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascended, Descending" }
quests[86952] = { id = 86952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Approach the Croach", objectives = "Defeat Creech in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86956] = { id = 86956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traveling Flowers", description = "Orweyna mentioned that there are rutaani who are visiting from other villages. This is an opportunity for us to get to know what they're like when they're not Light-crazed.\n\nI will stay here to speak with Meeka. You should speak with the visiting rutaani to determine whether the Lightbloom has reached their homes.", progress = "We must stop the spread of the Lightbloom! Determining its spread will help us fight it in the long run.", completion = "So there are no signs of Lightbloom yet in their villages? Meeka seems unchanged as well, and states that the rutaani never act in the manner of the Light-crazed.\n\nThis is both promising and frustrating.\n\nI am glad that it hasn't yet spread that far, but I suspect we shall find more soon.", objectives = "Talk to the visiting rutaani merchants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86957] = { id = 86957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakgor's Revenge" }
quests[86959] = { id = 86959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodeye Prisoners" }
quests[86960] = { id = 86960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Good Health", description = "I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?", objectives = "Find a key to open the chest and retrieve the antidote.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86961] = { id = 86961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diversified Investments", description = "<The letter is simply addressed to \"The {class} who took down Gallywix.\" It takes you a frustrating amount of time to rip open the multiple layers of duct tape sealing the envelope shut.>\n\nHey bud,\n\nYou've been gettin' a reputation for yourself. Not afraid to roll up your sleeves and get down to business. Certain people really value that kind of thing.\n\nLet's talk shop. Meet me in my warehouse and maybe we can agree on a business partnership.", completion = "Lookin' forward to doin' business with ya.", objectives = "Find your prospective \"business partner\" and speak to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86962] = { id = 86962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Wound", objectives = "Return the Antidote", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86973] = { id = 86973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halting Harm in Har'mara", description = "Lightbloom-infected rutaani are attacking the village! Rizam and Teetem both succumbed to the infection. It looks like Eonka hasn't been affected, but we must handle the others.\n\nI will stay here and keep an eye on her. I need you to do what you can to protect Har'mara. Take out Rizam and Teetem as well.", completion = "Tough, but needed work. May this slow the spread until we can find a way to stop it entirely.", objectives = "Slay 8 Lightbloom rutaani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
