quests[88754] = { id = 88754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply" }
quests[88755] = { id = 88755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholarly Pursuits", description = "{name}... a favor.\n\nMy research partner Matrean and I are studying the local wildlife and their relationship to the Void.\n\nI've concluded my findings, but Matrean--reckless and obsessive as ever--insists there is more to discover.\n\nCan you help convince him to return here?", completion = "The Void peers back, but I shall not avert my gaze.", objectives = "Meet with Kelia and Matrean in the Bladeburrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88768] = { id = 88768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agents of Darkness", description = "When that shield goes down, Xal'atath's forces will be upon us in droves. If I'm going to detonate those manacells from afar, I'll need an opening. Thin the Devouring Host of their strongest, and the rest of Xal'atath's lackeys will be easier to fight off.\n\nWe will make sure the shield goes down in the meantime. Good luck, {name}.", progress = "Have you taken them out?", completion = "I hope Xal'atath was watching. It'll be her turn soon.", objectives = "Slay Nexus-King Salhadaar's lieutenants within Nexus-Point Mid'Ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88771] = { id = 88771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loaknit Alphas!" }
quests[88772] = { id = 88772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammoth Remnants!" }
quests[88774] = { id = 88774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Energy" }
quests[88803] = { id = 88803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timely Assistance", description = "Hello, Champion.\n\nI have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass.\n\nI will form a construct that will assist you in the vision.", progress = "I hope you find this useful.", completion = "You may call upon this aid for any vision.", objectives = "Interact with the hourglass and gain Soridormi's assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88804] = { id = 88804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat the Mineraw!" }
quests[88805] = { id = 88805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarred Path Through Time", description = "Old enemies return and battle scars open once more.\n\nDefeat these foes and return with tales of glory.", completion = "What news from the war front?", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88808] = { id = 88808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarred Journey Through Time", description = "Azeroth calls out in need, champion. She bleeds still from wounds of war. Go forth among Zandalar and Kul Tiras to reveal those who would prolong her suffering.\n\nVanquish foes in her name and defend Azeroth.", completion = "I knew I could trust in you to complete such a feat.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88818] = { id = 88818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Sweeper" }
